document.addEventListener("DOMContentLoaded", () => {
  // Cats Gallery Tabs
  const catNavItems = document.querySelectorAll('.ats-cat-nav-item');
  
  catNavItems.forEach(navItem => {
      navItem.addEventListener('click', () => {
          const targetId = navItem.getAttribute('data-target');
          if (!targetId) return;

          // 1. Nav Active Toggle
          catNavItems.forEach(item => item.classList.remove('active'));
          navItem.classList.add('active');

          // 2. Panel Active Toggle
          const allPanels = document.querySelectorAll('.ats-cat-panel');
          allPanels.forEach(panel => {
              panel.classList.remove('active');
          });

          const targetPanel = document.getElementById(targetId);
          if (targetPanel) {
              targetPanel.classList.add('active');
          }
      });
  });
});

