document.addEventListener('DOMContentLoaded', function() {
  var modal = document.querySelector('.lp-modal-overlay');
  var closeBtn = document.querySelector('.lp-modal-close-btn');
  var modalImg = document.querySelector('.lp-modal-content');
  var items = document.querySelectorAll('.lp-voice-item');

  if (!modal || !closeBtn || !modalImg) return;

  // 画像クリックでモーダルを開く
  items.forEach(function(item) {
    item.addEventListener('click', function() {
      var img = item.querySelector('img');
      if (img) {
        modalImg.src = img.src;
        modalImg.style.display = 'block'; // 画像を表示
        modal.classList.add('active');
      }
    });
  });

  // モーダルを閉じる処理
  function closeMyModal() {
    modal.classList.remove('active');
    setTimeout(function(){ 
      modalImg.src = ''; 
      modalImg.style.display = 'none'; // 画像を非表示に
    }, 300);
  }

  closeBtn.addEventListener('click', function(e) {
    e.stopPropagation();
    closeMyModal();
  });

  modal.addEventListener('click', function(e) {
    if (e.target === modal) {
      closeMyModal();
    }
  });
});

